class IdentityLesson(Lesson):
    '''Lesson 3.8: Identity Operators - The Same or Different'''

    def __init__(self):
        super().__init__(
            lesson_id="identity",
            title="The Same or Different - Identity Operators",
            description="Understand object identity with is and is not"
        )

        self.key_concepts = [
            "'is' checks if two variables reference the SAME object in memory (identity)",
            "'is not' checks if two variables reference DIFFERENT objects",
            "'==' checks equality (same value), 'is' checks identity (same object)",
            "ALWAYS use 'is None' and 'is not None' for None checks (not '== None')",
            "id() function returns unique identifier for each object"
        ]

        self.common_pitfalls = [
            "Using 'is' for value comparison: 'x is 5' unreliable, use 'x == 5'",
            "Not understanding small integer caching (-5 to 256): 'a is b' may be True",
            "Using '== None' instead of 'is None' (works but not Pythonic)",
            "Expecting 'is' to work for comparing list/dict contents (use '==')",
            "Confusing identity with equality: two equal lists aren't the same object"
        ]

        self.best_practices = [
            "ALWAYS use 'is None' and 'is not None' for None checks",
            "Use 'is' only for singletons: None, True, False (and rarely True/False)",
            "Use '==' for all value comparisons (numbers, strings, collections)",
            "Use 'is' when you specifically need to check object identity",
            "Use id() function to understand object identity when debugging"
        ]

        self.real_world_apps = [
            "None checks: Validating optional parameters, database query results",
            "Singleton pattern: Ensuring only one instance of a class exists",
            "Identity verification: Checking if two variables point to same object",
            "Debugging: Using id() to understand object references and mutations",
            "Optimization: Checking if function returned cached result vs new object"
        ]

