    json_count = len(list(data_dir.glob("*.json")))
    csv_count = len(list(data_dir.glob("*.csv")))
    txt_count = len(list(data_dir.glob("*.txt")))

    print(f"JSON files: {json_count}")
    print(f"CSV files: {csv_count}")
    print(f"Text files: {txt_count}")

