    '''Main game class.'''

    from pathlib import Path
    from .utils.config import Config
    from .entities.player import Player

    class Game:
        '''Main game controller.'''

        def __init__(self):
            self.config = Config()
            self.player = None
            self.running = False

        def run(self):
            '''Main game loop.'''
            self.setup()
            self.running = True

            while self.running:
                self.update()

        def setup(self):
            '''Initialize game.'''
            player_name = input("Enter your name: ")
            self.player = Player(player_name)
            print(f"Welcome, {player_name}!")

        def update(self):
            '''Update game state.'''
            print("\\n1. Adventure")
            print("2. Inventory")
            print("3. Quit")

            choice = input("Choice: ")

            if choice == "3":
                self.running = False

