    '''
    Complete RPG game with professional save system.
    '''

    from pathlib import Path
    from datetime import datetime

    # Assume SaveSystem class from above is available

    class Player:
        '''Player character.'''

        def __init__(self, name):
            self.name = name
            self.level = 1
            self.xp = 0
            self.hp = 100
            self.max_hp = 100
            self.gold = 0
            self.inventory = []
            self.location = "Village"

        def to_dict(self):
            '''Convert to dictionary for saving.'''
            return {
                'name': self.name,
                'level': self.level,
                'xp': self.xp,
                'hp': self.hp,
                'max_hp': self.max_hp,
                'gold': self.gold,
                'inventory': self.inventory,
                'location': self.location
            }

        @staticmethod
        def from_dict(data):
            '''Create player from saved data.'''
            player = Player(data['name'])
            player.level = data['level']
            player.xp = data['xp']
            player.hp = data['hp']
            player.max_hp = data['max_hp']
            player.gold = data['gold']
            player.inventory = data['inventory']
            player.location = data['location']
            return player

    class Game:
        '''Main game with save system.'''

        def __init__(self):
            self.player = None
            self.save_system = SaveSystem()
            self.current_slot = None
            self.running = False

        def run(self):
            '''Main game loop.'''
            self.show_title()
            self.main_menu()

        def show_title(self):
            '''Show title screen.'''
            print("\\n" + "=" * 50)
            print("  VERDANT QUEST - The RPG Adventure")
            print("=" * 50)

        def main_menu(self):
            '''Main menu.'''
            while True:
                print("\\n1. New Game")
                print("2. Load Game")
                print("3. Delete Save")
                print("4. Quit")

                choice = input("\\nChoice: ").strip()

                if choice == "1":
                    self.new_game()
                elif choice == "2":
                    self.load_game_menu()
                elif choice == "3":
                    self.delete_save_menu()
                elif choice == "4":
                    break

        def new_game(self):
            '''Start new game.'''
            print("\\n=== NEW GAME ===")

            # Get player name
            name = input("Enter your name: ").strip()
            if not name:
                name = "Hero"

            # Create player
            self.player = Player(name)

            # Get save slot
            slot = input("Save slot name: ").strip()
            if not slot:
                slot = f"{name}_{datetime.now():%Y%m%d}"

            self.current_slot = slot

            print(f"\\nWelcome, {name}!")
            print("Your adventure begins...")

            # Start game loop
            self.game_loop()

        def load_game_menu(self):
            '''Show load game menu.'''
            print("\\n=== LOAD GAME ===")

            # List saves
            saves = self.save_system.list_saves()

            if not saves:
                print("No save files found")
                input("\\n[Press Enter]")
                return

            print("\\nAvailable saves:")
            for i, save in enumerate(saves, 1):
                timestamp = save['timestamp'][:19].replace('T', ' ')
                size_kb = save['size'] / 1024
                print(f"{i}. {save['slot']}")
                print(f"   Saved: {timestamp}")
                print(f"   Size: {size_kb:.1f} KB")

            # Get choice
            choice = input("\\nLoad save (number or 0 to cancel): ").strip()

            try:
                idx = int(choice) - 1
                if 0 <= idx < len(saves):
                    slot = saves[idx]['slot']
                    self.load_game(slot)
            except ValueError:
                pass

        def load_game(self, slot_name: str):
            '''Load game from slot.'''
            print(f"\\nLoading game from '{slot_name}'...")

            # Load save data
            game_data = self.save_system.load_game(slot_name)

            if game_data is None:
                print("Failed to load game")
                input("\\n[Press Enter]")
                return

            # Restore player
            self.player = Player.from_dict(game_data['player'])
            self.current_slot = slot_name

            print(f"\\nWelcome back, {self.player.name}!")
            print(f"Level {self.player.level} | {self.player.location}")

            # Continue game
            self.game_loop()

        def delete_save_menu(self):
            '''Delete save menu.'''
            print("\\n=== DELETE SAVE ===")

            saves = self.save_system.list_saves()

            if not saves:
                print("No save files to delete")
                input("\\n[Press Enter]")
                return

            print("\\nSave files:")
            for i, save in enumerate(saves, 1):
                print(f"{i}. {save['slot']}")

            choice = input("\\nDelete save (number or 0 to cancel): ").strip()

            try:
                idx = int(choice) - 1
                if 0 <= idx < len(saves):
                    slot = saves[idx]['slot']
                    print(f"Delete '{slot}'? (y/n)")
                    if input().strip().lower() == 'y':
                        self.save_system.delete_save(slot)
            except ValueError:
                pass

            input("\\n[Press Enter]")

        def game_loop(self):
            '''Main game loop.'''
            self.running = True

            while self.running:
                self.show_status()
                self.game_menu()

        def show_status(self):
            '''Show player status.'''
            print("\\n" + "=" * 50)
            print(f"{self.player.name} | Level {self.player.level}")
            print(f"HP: {self.player.hp}/{self.player.max_hp} | Gold: {self.player.gold}")
            print(f"Location: {self.player.location}")
            print("=" * 50)

        def game_menu(self):
            '''In-game menu.'''
            print("\\n1. Adventure")
            print("2. Inventory")
            print("3. Save Game")
            print("4. Return to Main Menu")

            choice = input("\\nChoice: ").strip()

            if choice == "1":
                self.adventure()
            elif choice == "2":
                self.show_inventory()
            elif choice == "3":
                self.save_game()
            elif choice == "4":
                print("\\nReturn to main menu? (y/n)")
                if input().strip().lower() == 'y':
                    self.running = False

        def adventure(self):
            '''Simple adventure event.'''
            print("\\nYou venture forth...")
            print("You find 10 gold!")

            self.player.gold += 10
            self.player.xp += 5

            if self.player.xp >= self.player.level * 10:
                self.player.level += 1
                self.player.xp = 0
                self.player.max_hp += 10
                self.player.hp = self.player.max_hp
                print(f"\\n*** LEVEL UP! Now level {self.player.level} ***")

            input("\\n[Press Enter]")

        def show_inventory(self):
            '''Show inventory.'''
            print("\\n=== INVENTORY ===")

            if not self.player.inventory:
                print("Empty")
            else:
                for item in self.player.inventory:
                    print(f"  - {item}")

            input("\\n[Press Enter]")

        def save_game(self):
            '''Save current game.'''
            print("\\n=== SAVE GAME ===")

            # Prepare save data
            game_data = {
                'player': self.player.to_dict(),
                'play_time': 0,  # Could track actual play time
            }

            # Save
            success = self.save_system.save_game(
                self.current_slot,
                game_data,
                compress=True
            )

            if success:
                print("Game saved successfully!")
            else:
                print("Failed to save game")

            input("\\n[Press Enter]")

    # Run game
    if __name__ == "__main__":
        game = Game()
        game.run()

