    class Skill:
        # Class attributes - shared configuration
        SKILL_COSTS = {
            "fireball": 20,
            "heal": 15,
            "shield": 10
        }

        mana_cost_modifier = 1.0  # Can adjust globally

        def __init__(self, name, caster_level):
            self.name = name
            self.caster_level = caster_level

