    class SkillTree:
        '''Manages learned skills.'''

        def __init__(self):
            self.skills = {}

        def __len__(self):
            return len(self.skills)

        def __getitem__(self, skill_name):
            if skill_name not in self.skills:
                raise KeyError(f"Skill '{skill_name}' not learned")
            return self.skills[skill_name]

        def __setitem__(self, skill_name, level):
            if not isinstance(level, int) or level < 1:
                raise ValueError("Level must be positive integer")
            self.skills[skill_name] = level

        def __contains__(self, skill_name):
            return skill_name in self.skills

        def learn(self, skill_name, level=1):
            self[skill_name] = level

        def level_up(self, skill_name):
            if skill_name in self:
                self[skill_name] += 1
            else:
                self.learn(skill_name, 1)

    skills = SkillTree()
    skills.learn("Fireball", 1)
    skills.level_up("Fireball")

    print("Fireball" in skills)  # True
    print(skills["Fireball"])    # 2

