    class SaveFileManager:
        '''Manages multiple save slots.'''

        def __init__(self, num_slots=3):
            self.saves = [None] * num_slots

        def __len__(self):
            '''Number of save slots.'''
            return len(self.saves)

        def __getitem__(self, slot):
            '''Get save data from slot.'''
            if not 0 <= slot < len(self):
                raise IndexError(f"Invalid slot {slot}")
            return self.saves[slot]

        def __setitem__(self, slot, save_data):
            '''Save data to slot.'''
            if not 0 <= slot < len(self):
                raise IndexError(f"Invalid slot {slot}")
            self.saves[slot] = save_data

        def __contains__(self, slot):
            '''Check if slot has save data.'''
            if isinstance(slot, int):
                return 0 <= slot < len(self) and self.saves[slot] is not None
            return False

        def clear_slot(self, slot):
            self[slot] = None

    saves = SaveFileManager(3)
    saves[0] = {"player": "Grixle", "level": 25}

    print(len(saves))  # 3 slots
    print(0 in saves)  # True (has data)
    print(1 in saves)  # False (empty)

