    orc = Enemy("Orc Berserker", "orc", x=20, y=20, max_health=80, strength=12)

    print(f"\\nPlayer stats: {player.render()}")
    print(f"Enemy 1: {goblin.render()}")
    print(f"Enemy 2: {orc.render()}")

    # Combat simulation
    print("\\n=== COMBAT BEGINS ===")
    goblin.attack(player)
    player.take_damage(15)

    # Player defeats goblin
    goblin.take_damage(100)
    if not goblin.stats.is_alive():
        player.gain_xp(goblin.xp_reward)
        player.gold += goblin.gold_reward

    # Serialization (from SerializableMixin)
    print("\\n=== SERIALIZATION ===")
    player_json = player.to_json()
    print(f"Player JSON: {player_json[:100]}...")

    # Demonstrate polymorphism
    print("\\n=== POLYMORPHISM ===")
    entities: List[Entity] = [player, orc]
    for entity in entities:
        print(entity.render())  # Same method, different behavior!
        entity.update(1.0)

    # Compare characters (using __lt__ magic method)
    print("\\n=== COMPARISON ===")
    if player.level > goblin.level:
        print(f"{player.name} is higher level than {goblin.name}")

    # Class method
    print(f"\\nTotal players created: {Player.get_player_count()}")

    # Quest system
    print(f"\\n=== QUEST ===")
    print(f"Quest: {quest1.title}")
    print(f"Description: {quest1.description}")
    print(f"Rewards: {quest1.xp_reward} XP, {quest1.gold_reward} gold")

