    class PlayerProgress:
        def __init__(self):
            self.rounds = []

        def add_round_scores(self, round_scores):
            '''Add scores for a round and sort.'''
            for score_entry in round_scores:
                self.rounds.append(score_entry)

        def get_leaderboard(self, round_num):
            '''Get sorted leaderboard for specific round.'''
            round_scores = [s for s in self.rounds if s.round == round_num]

            # Sort by score descending
            n = len(round_scores)
            for i in range(n):
                for j in range(n - 1 - i):
                    if round_scores[j].score < round_scores[j + 1].score:
                        round_scores[j], round_scores[j + 1] = round_scores[j + 1], round_scores[j]

            return round_scores

