    def insertion_sort(items):
        '''Build sorted portion by inserting each element.'''
        for i in range(1, len(items)):
            key = items[i]  # Element to insert
            j = i - 1

            # Shift elements right until finding correct position
            while j >= 0 and items[j] > key:
                items[j + 1] = items[j]  # Shift right
                j -= 1

            items[j + 1] = key  # Insert at correct position

    scores = [40, 10, 50, 20, 30]
