    def debug_combat():
        player = Player('Grixle', hp=100, attack=20)
        enemy = Enemy('Goblin', hp=50, attack=10)

        print("=== COMBAT START ===")
        print(f"Player: {player.hp} HP, {player.attack} ATK")
        print(f"Enemy: {enemy.hp} HP, {enemy.attack} ATK")

        round_num = 1
        while player.hp > 0 and enemy.hp > 0:
            print(f"\n--- Round {round_num} ---")

            # Player turn
            print(f"Player attacks for {player.attack}")
            enemy.hp -= player.attack
            print(f"Enemy HP: {enemy.hp}")

            if enemy.hp <= 0:
                print("Enemy defeated!")
                break

            # Enemy turn
            print(f"Enemy attacks for {enemy.attack}")
            player.hp -= enemy.attack
            print(f"Player HP: {player.hp}")

            if player.hp <= 0:
                print("Player defeated!")
                break

            round_num += 1

        print("\n=== COMBAT END ===")

