    def heal_character(character, amount):
        '''Heal character by amount, capping at max HP.'''
        if character is None:
            raise ValueError("Character cannot be None")
        if amount < 0:
            raise ValueError("Heal amount must be positive")

        character.hp = min(character.hp + amount, character.max_hp)
        return character

