    import sqlite3

    # Connect to database (creates file if not exists)
    conn = sqlite3.connect('game.db')
    cursor = conn.cursor()

    # Create table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS players (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL,
            level INTEGER,
            xp INTEGER
        )
    ''')

    # Insert player
    cursor.execute(
        "INSERT INTO players (name, level, xp) VALUES (?, ?, ?)",
        ("Grixle", 10, 1000)
    )

    # Save changes
    conn.commit()

    # Query players
    cursor.execute("SELECT * FROM players")
    for row in cursor.fetchall():
        print(row)  # (1, 'Grixle', 10, 1000)

    conn.close()

