    # src/awesome_project/core/models.py
    # -*- coding: utf-8 -*-
    '''
    Core data models for awesome project.

    This module defines the primary data structures used throughout
    the application, following best practices and PEP 8 style.
    '''

    from typing import List, Optional, Dict
    from dataclasses import dataclass
    from datetime import datetime


    @dataclass
    class User:
        '''User model with validation and clean methods.'''

        user_id: int
        username: str
        email: str
        created_at: datetime

        def __post_init__(self):
            '''Validate user data after initialization.'''
            if not self.username:
                raise ValueError("Username cannot be empty")

            if '@' not in self.email:
                raise ValueError("Invalid email format")

        def to_dict(self) -> Dict[str, any]:
            '''Convert user to dictionary.'''
            return {
                'user_id': self.user_id,
                'username': self.username,
                'email': self.email,
                'created_at': self.created_at.isoformat()
            }

        @classmethod
        def from_dict(cls, data: Dict[str, any]) -> 'User':
            '''Create user from dictionary.'''
            return cls(
                user_id=data['user_id'],
                username=data['username'],
                email=data['email'],
                created_at=datetime.fromisoformat(data['created_at'])
            )


    class UserManager:
        '''Manage user operations with clean API.'''

        def __init__(self):
            self._users: Dict[int, User] = {}
            self._next_id = 1

        def create_user(self, username: str, email: str) -> User:
            '''Create new user with validation.'''
            user = User(
                user_id=self._next_id,
                username=username,
                email=email,
                created_at=datetime.now()
            )

            self._users[user.user_id] = user
            self._next_id += 1

            return user

        def get_user(self, user_id: int) -> Optional[User]:
            '''Get user by ID, return None if not found.'''
            return self._users.get(user_id)

        def get_all_users(self) -> List[User]:
            '''Get all users sorted by creation date.'''
            return sorted(self._users.values(),
                         key=lambda u: u.created_at)

        def delete_user(self, user_id: int) -> bool:
            '''Delete user, return True if deleted.'''
            if user_id in self._users:
                del self._users[user_id]
                return True
            return False

