    # src/awesome_project/web/app.py
    '''
    Flask web application for user management.

    Professional Flask app with routes, templates, and API endpoints.
    '''

    from flask import Flask, render_template, request, jsonify, redirect, url_for
    from awesome_project.core.models import UserManager

    app = Flask(__name__)
    user_manager = UserManager()


    @app.route('/')
    def home():
        '''Home page showing all users.'''
        users = user_manager.get_all_users()
        return render_template('home.html', users=users)


    @app.route('/user/<int:user_id>')
    def user_profile(user_id):
        '''Individual user profile page.'''
        user = user_manager.get_user(user_id)

        if not user:
            return render_template('404.html'), 404

        return render_template('user.html', user=user)


    @app.route('/create', methods=['GET', 'POST'])
    def create_user():
        '''Create new user.'''
        if request.method == 'POST':
            username = request.form['username']
            email = request.form['email']

            try:
                user = user_manager.create_user(username, email)
                return redirect(url_for('user_profile', user_id=user.user_id))
            except ValueError as e:
                return render_template('create.html', error=str(e))

        return render_template('create.html')


    # API Endpoints
    @app.route('/api/users')
    def api_get_users():
        '''Get all users as JSON.'''
        users = user_manager.get_all_users()
        return jsonify([user.to_dict() for user in users])


    @app.route('/api/users/<int:user_id>')
    def api_get_user(user_id):
        '''Get single user as JSON.'''
        user = user_manager.get_user(user_id)

        if not user:
            return jsonify({'error': 'User not found'}), 404

        return jsonify(user.to_dict())


    @app.route('/api/users', methods=['POST'])
    def api_create_user():
        '''Create user via API.'''
        data = request.get_json()

        try:
            user = user_manager.create_user(
                data['username'],
                data['email']
            )
            return jsonify(user.to_dict()), 201
        except (ValueError, KeyError) as e:
            return jsonify({'error': str(e)}), 400


    @app.errorhandler(404)
    def not_found(error):
        '''Custom 404 page.'''
        return render_template('404.html'), 404


    if __name__ == '__main__':
        app.run(debug=True)

