    # src/awesome_project/database/db.py
    '''
    Database layer using SQLite.

    Professional database operations with proper error handling.
    '''

    import sqlite3
    from typing import List, Optional
    from contextlib import contextmanager
    from awesome_project.core.models import User
    from datetime import datetime


    class Database:
        '''Database operations manager.'''

        def __init__(self, db_path: str = 'users.db'):
            self.db_path = db_path
            self._init_db()

        @contextmanager
        def _get_connection(self):
            '''Context manager for database connections.'''
            conn = sqlite3.connect(self.db_path)
            conn.row_factory = sqlite3.Row
            try:
                yield conn
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

        def _init_db(self):
            '''Initialize database schema.'''
            with self._get_connection() as conn:
                conn.execute('''
                    CREATE TABLE IF NOT EXISTS users (
                        user_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        username TEXT NOT NULL UNIQUE,
                        email TEXT NOT NULL,
                        created_at TEXT NOT NULL
                    )
                ''')

        def create_user(self, username: str, email: str) -> User:
            '''Create user in database.'''
            created_at = datetime.now()

            with self._get_connection() as conn:
                cursor = conn.execute(
                    'INSERT INTO users (username, email, created_at) VALUES (?, ?, ?)',
                    (username, email, created_at.isoformat())
                )

                user_id = cursor.lastrowid

            return User(user_id, username, email, created_at)

        def get_user(self, user_id: int) -> Optional[User]:
            '''Get user by ID.'''
            with self._get_connection() as conn:
                row = conn.execute(
                    'SELECT * FROM users WHERE user_id = ?',
                    (user_id,)
                ).fetchone()

                if row:
                    return User(
                        user_id=row['user_id'],
                        username=row['username'],
                        email=row['email'],
                        created_at=datetime.fromisoformat(row['created_at'])
                    )

            return None

        def get_all_users(self) -> List[User]:
            '''Get all users.'''
            with self._get_connection() as conn:
                rows = conn.execute(
                    'SELECT * FROM users ORDER BY created_at DESC'
                ).fetchall()

                return [
                    User(
                        user_id=row['user_id'],
                        username=row['username'],
                        email=row['email'],
                        created_at=datetime.fromisoformat(row['created_at'])
                    )
                    for row in rows
                ]

