    # src/awesome_project/scraper/wiki_scraper.py
    '''
    Web scraper for gathering data from external sources.

    Ethical scraping with rate limiting and error handling.
    '''

    import requests
    from bs4 import BeautifulSoup
    import time
    from typing import List, Dict


    class WikiScraper:
        '''Scrape data from wiki pages ethically.'''

        def __init__(self, base_url: str, delay: float = 1.0):
            self.base_url = base_url
            self.delay = delay
            self.session = requests.Session()
            self.session.headers.update({
                'User-Agent': 'AwesomeProject/1.0 (Educational Purpose)'
            })

        def scrape_page(self, path: str) -> Dict[str, any]:
            '''Scrape single page with error handling.'''
            url = f"{self.base_url}{path}"

            try:
                response = self.session.get(url, timeout=10)
                response.raise_for_status()

                soup = BeautifulSoup(response.text, 'html.parser')

                # Extract data (example)
                title = soup.find('h1').text if soup.find('h1') else 'No title'
                content = soup.find('div', class_='content')
                text = content.get_text() if content else ''

                # Polite delay
                time.sleep(self.delay)

                return {
                    'title': title,
                    'text': text.strip(),
                    'url': url,
                    'success': True
                }

            except Exception as e:
                return {
                    'error': str(e),
                    'url': url,
                    'success': False
                }

        def scrape_multiple(self, paths: List[str]) -> List[Dict[str, any]]:
            '''Scrape multiple pages with rate limiting.'''
            results = []

            for i, path in enumerate(paths):
                print(f"Scraping {i+1}/{len(paths)}: {path}")
                result = self.scrape_page(path)
                results.append(result)

            return results

