from threading import Lock

# Non-reentrant (can't nest)
lock = Lock()

with lock:
    # with lock:  # DEADLOCK!
    pass

# Reentrant (can nest)
from threading import RLock

rlock = RLock()

with rlock:
    with rlock:  # OK!
        pass

