# Sanitizing HTML (allow some tags)
import bleach

def sanitize_html(dirty_html):
    # Allow only safe tags and attributes
    clean = bleach.clean(
        dirty_html,
        tags=['p', 'br', 'strong', 'em', 'a'],
        attributes={'a': ['href', 'title']},
        strip=True
    )
    return clean

